
.world-section {
  padding: 10px;
  background: linear-gradient(180deg, var(--c-iron) 0%, var(--c-obsidian) 100%);
}

.throne-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  background: linear-gradient(90deg, rgba(201, 168, 76, 0.2) 0%, transparent 100%);
  border-left: 3px solid var(--c-gold);
  margin-bottom: 8px;
  font-size: 0.9rem;
}

.throne-icon {
  font-size: 1rem;
}

.throne-text {
  color: var(--c-gold);
  font-weight: bold;
  letter-spacing: 1px;
}

.meta-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 8px;
  font-size: 0.82rem;
  border-bottom: 1px dashed var(--c-steel);
  padding-bottom: 6px;
  flex-wrap: wrap;
  gap: 4px;
}

.meta-item {
  display: flex;
  align-items: center;
  gap: 4px;
}

.meta-label {
  font-size: 0.8rem;
}

.situation-bar {
  padding: 5px 8px;
  background: rgba(139, 37, 0, 0.15);
  border-left: 2px solid var(--c-blood);
  margin-bottom: 8px;
  font-size: 0.8rem;
  line-height: 1.3;
}

.situation-label {
  color: var(--c-fire);
  font-weight: bold;
  margin-right: 6px;
}

.situation-text {
  color: var(--c-parchment);
}

.event-list {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 2px;
}

.event-badge {
  background: rgba(74, 74, 106, 0.3);
  border: 1px solid var(--c-steel);
  padding: 6px 8px;
  min-width: 130px;
  flex: 1;
  position: relative;
}

.event-badge::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--c-gold);
}

.event-title {
  display: block;
  font-weight: bold;
  margin-bottom: 2px;
  padding-left: 6px;
  color: var(--c-gold);
  font-size: 0.78rem;
}

.event-desc {
  display: block;
  font-size: 0.72rem;
  color: var(--c-silver);
  padding-left: 6px;
}

@media (max-width: 600px) {
  .meta-row {
    flex-direction: column;
    gap: 4px;
  }

  .event-list {
    flex-direction: column;
  }

  .event-badge {
    min-width: auto;
  }
}
