
.npc-layout {
  position: relative;
}

.section-head {
  font-size: 0.88rem;
  border-bottom: 1px solid var(--c-gold);
  display: inline-block;
  padding-bottom: 2px;
  margin-bottom: 8px;
  font-weight: bold;
  color: var(--c-gold);
}

.npc-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.npc-card {
  position: relative;
  padding: 8px 10px;
  background: rgba(74, 74, 106, 0.2);
  border: 1px solid var(--c-steel);
  transition: background 0.2s;
}

.npc-card:hover {
  background: rgba(74, 74, 106, 0.35);
}

.delete-btn {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 20px;
  height: 20px;
  border: 1px solid var(--c-steel);
  background: rgba(139, 37, 0, 0.3);
  color: var(--c-fire);
  font-size: 0.7rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.5;
  transition:
    opacity 0.2s,
    background 0.2s;
  padding: 0;
  font-family: inherit;
}

.delete-btn:hover {
  opacity: 1;
  background: rgba(139, 37, 0, 0.6);
}

.npc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 4px;
  padding-right: 22px;
}

.npc-name {
  font-weight: bold;
  font-size: 0.88rem;
  color: var(--c-parchment);
}

.npc-status {
  font-size: 0.7rem;
  padding: 1px 5px;
  border-radius: 2px;
}

.status-alive {
  background: rgba(76, 175, 80, 0.3);
  color: #4caf50;
}
.status-wounded {
  background: rgba(255, 152, 0, 0.3);
  color: #ff9800;
}
.status-dead {
  background: rgba(231, 76, 60, 0.3);
  color: var(--c-fire);
  text-decoration: line-through;
}
.status-other {
  background: rgba(142, 142, 160, 0.3);
  color: var(--c-silver);
}

.npc-info {
  display: flex;
  gap: 8px;
  margin-bottom: 3px;
  flex-wrap: wrap;
}

.info-tag {
  font-size: 0.72rem;
  color: var(--c-silver);
}

.affinity-section {
  margin-top: 4px;
}

.affinity-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 3px;
}

.affinity-label {
  font-size: 0.72rem;
  color: var(--c-silver);
}

.affinity-value {
  font-size: 0.75rem;
  font-weight: bold;
}

.affinity-high {
  color: #4caf50;
}
.affinity-positive {
  color: var(--c-ice);
}
.affinity-neutral {
  color: var(--c-silver);
}
.affinity-negative {
  color: #ff9800;
}
.affinity-hostile {
  color: var(--c-fire);
}

.affinity-track {
  height: 6px;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid var(--c-steel);
  position: relative;
  overflow: hidden;
}

.affinity-center {
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--c-parchment);
  opacity: 0.5;
}

.affinity-fill {
  position: absolute;
  top: 0;
  bottom: 0;
  transition: width 0.3s ease;
}

.affinity-fill.positive {
  background: linear-gradient(90deg, var(--c-ice) 0%, #4caf50 100%);
}

.affinity-fill.negative {
  background: linear-gradient(270deg, var(--c-fire) 0%, #ff9800 100%);
}

.empty-state {
  text-align: center;
  color: var(--c-silver);
  padding: 15px;
  font-style: italic;
  font-size: 0.82rem;
}

/* 确认对话框 */
.confirm-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.confirm-dialog {
  background: var(--c-iron);
  border: 2px solid var(--c-gold);
  padding: 16px 20px;
  max-width: 300px;
  width: 90%;
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.5);
}

.confirm-text {
  color: var(--c-parchment);
  font-size: 0.85rem;
  margin-bottom: 6px;
  text-align: center;
}

.confirm-text-sub {
  color: var(--c-silver);
  font-size: 0.72rem;
  margin-bottom: 12px;
  text-align: center;
}

.confirm-actions {
  display: flex;
  gap: 8px;
  justify-content: center;
}

.btn-cancel,
.btn-confirm {
  padding: 5px 14px;
  border: 1px solid var(--c-steel);
  font-family: var(--font-label);
  font-size: 0.78rem;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-cancel {
  background: transparent;
  color: var(--c-silver);
}

.btn-cancel:hover {
  background: rgba(142, 142, 160, 0.2);
}

.btn-confirm {
  background: rgba(139, 37, 0, 0.4);
  color: var(--c-fire);
  border-color: var(--c-blood);
}

.btn-confirm:hover {
  background: rgba(139, 37, 0, 0.7);
}
