
.user-layout {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.identity-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
}

.identity-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  background: rgba(74, 74, 106, 0.2);
  border-left: 2px solid var(--c-steel);
}

.label {
  color: var(--c-silver);
  font-size: 0.75rem;
  min-width: 28px;
}

.value {
  color: var(--c-parchment);
  font-size: 0.82rem;
  font-weight: bold;
}

.health-good {
  color: #4caf50;
}
.health-minor {
  color: var(--c-gold);
}
.health-hurt {
  color: #ff9800;
}
.health-critical {
  color: var(--c-fire);
}

.resource-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.resource-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 3px 0;
}

.resource-label {
  font-size: 0.78rem;
  min-width: 60px;
  color: var(--c-silver);
}

.bar-track {
  flex: 1;
  height: 8px;
  border: 1px solid var(--c-steel);
  background: rgba(0, 0, 0, 0.3);
  position: relative;
  overflow: hidden;
}

.bar-fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  transition: width 0.3s ease;
}

.bar-fill.reputation {
  background: linear-gradient(90deg, var(--c-steel) 0%, var(--c-gold) 100%);
}

.resource-value {
  font-size: 0.82rem;
  font-weight: bold;
  min-width: 30px;
  text-align: right;
}

.resource-value.gold {
  color: var(--c-lannister-gold);
}

.section-head {
  font-size: 0.88rem;
  border-bottom: 1px solid var(--c-gold);
  display: inline-block;
  padding-bottom: 2px;
  margin-bottom: 4px;
  font-weight: bold;
  color: var(--c-gold);
}

.skills-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 6px;
}

.skill-item {
  padding: 5px 8px;
  background: rgba(74, 74, 106, 0.2);
  border: 1px solid var(--c-steel);
}

.skill-header {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 3px;
}

.skill-icon {
  font-size: 0.8rem;
}

.skill-name {
  font-size: 0.78rem;
  font-weight: bold;
  flex: 1;
}

.skill-value {
  font-size: 0.75rem;
  color: var(--c-gold);
  font-weight: bold;
}

.skill-track {
  height: 4px;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid var(--c-steel);
  overflow: hidden;
  margin-bottom: 2px;
}

.skill-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--c-ice) 0%, var(--c-gold) 50%, var(--c-fire) 100%);
  transition: width 0.3s ease;
}

.skill-rank {
  font-size: 0.65rem;
  color: var(--c-silver);
  font-style: italic;
}

.inventory-grid {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.item-row {
  display: flex;
  align-items: center;
  border: 1px solid var(--c-steel);
  padding: 6px 8px;
  background: rgba(74, 74, 106, 0.15);
  transition:
    transform 0.2s,
    background 0.2s;
}

.item-row:hover {
  transform: translateX(3px);
  background: rgba(74, 74, 106, 0.3);
}

.item-icon {
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 8px;
  font-size: 1rem;
}

.item-detail {
  flex: 1;
}

.item-name {
  font-weight: bold;
  display: block;
  font-size: 0.82rem;
}

.item-desc {
  font-size: 0.72rem;
  color: var(--c-silver);
}

.item-count {
  background: var(--c-steel);
  color: var(--c-parchment);
  padding: 2px 5px;
  font-size: 0.7rem;
  border-radius: 2px;
}

.empty-state {
  text-align: center;
  color: var(--c-silver);
  padding: 15px;
  font-style: italic;
  font-size: 0.82rem;
}

@media (max-width: 600px) {
  .identity-section {
    grid-template-columns: 1fr;
  }

  .skills-grid {
    grid-template-columns: 1fr;
  }
}
